import styles from "./index.module.scss";

const StatusIcon = () => {
  return (
    <svg
      width="12"
      height="18"
      viewBox="0 0 12 18"
      xmlns="http://www.w3.org/2000/svg"
    >
      <path d="M6 9C6 10.6569 4.65685 12 3 12C1.34315 12 0 10.6569 0 9C0 7.34315 1.34315 6 3 6C4.65685 6 6 7.34315 6 9Z" />
    </svg>
  );
};

const TrendingIcon = () => {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width="16"
      height="16"
      fill="#ff9500"
      viewBox="0 0 256 256"
    >
      <path d="M143.38,17.85a8,8,0,0,0-12.63,3.41l-22,60.41L84.59,58.26a8,8,0,0,0-11.93.89C51,87.53,40,116.08,40,144a88,88,0,0,0,176,0C216,84.55,165.21,36,143.38,17.85Zm40.51,135.49a57.6,57.6,0,0,1-46.56,46.55A7.65,7.65,0,0,1,136,200a8,8,0,0,1-1.32-15.89c16.57-2.79,30.63-16.85,33.44-33.45a8,8,0,0,1,15.78,2.68Z"></path>
    </svg>
  );
};

export default function WorkFlowStatus({ status }) {
  const colors = {
    inProgress: "#007AFF",
    inTesting: "#FF9500",
    finished: "#34C759",
    comingSoon: "#8E8E93",
  };

  const inPrgress = {
    borderColor: colors.inProgress,
    color: colors.inProgress,
    fill: colors.inProgress,
  };
  const inTesting = {
    borderColor: colors.inTesting,
    color: colors.inTesting,
    fill: colors.inTesting,
  };
  const finished = {
    borderColor: colors.finished,
    color: colors.finished,
    fill: colors.finished,
  };
  const comingSoon = {
    borderColor: colors.comingSoon,
    color: colors.comingSoon,
    fill: colors.comingSoon,
  };

  return (
    <div className={`${styles.flowBadge}`}>
      {(() => {
        switch (status) {
          case "In Progress":
            return (
              <span style={inPrgress}>
                <StatusIcon /> {status}
              </span>
            );
          case "Trending":
            return (
              <span style={inTesting}>
                <TrendingIcon /> {status}
              </span>
            );
          case "Finished":
            return (
              <span style={finished}>
                <StatusIcon /> {status}
              </span>
            );
          case "Coming Soon":
            return (
              <span style={comingSoon}>
                <StatusIcon /> {status}
              </span>
            );
          default:
            return null;
        }
      })()}
    </div>
  );
}
